<script setup>
import { ref,onMounted,onActivated } from 'vue'
import { api } from '../api'
import { useWorkflowWrite } from '../composables/useWorkflowWrite'
const emit=defineEmits(['changed'])
const props=defineProps({compact:Boolean,summaryOnly:Boolean}),data=ref(null),minutes=ref(0),region=ref(''),timezone=ref('Asia/Shanghai'),acknowledge=ref(false),error=ref(''),notice=ref(''),writes=useWorkflowWrite('trial')
async function load(){try{data.value=await api.flow('/trial');minutes.value=data.value.config?.base_minutes||0;region.value=data.value.config?.region||'';timezone.value=data.value.config?.pending_timezone||data.value.config?.timezone||'Asia/Shanghai'}catch(e){error.value=e.message}}
async function adopt(){try{await writes.send('/trial',{expected_version:data.value.config?.version||0,acknowledge:acknowledge.value,base_minutes:minutes.value,region:region.value,timezone:timezone.value},'PUT');await load();notice.value='未来采用试用规则；旧余额与旧券保留。';emit('changed')}catch(e){error.value=e.message}}
async function claim(){try{const result=await writes.send('/trial/first-record/claim',{expected_version:data.value.daily.version});await load();notice.value='首记签到 +'+result.coins_gained+' 币。';emit('changed')}catch(e){error.value=e.message}}
onMounted(load)
onActivated(()=>{if(data.value)load()})
</script>
<template><section class="card"><h2>{{ compact?'首记与休息':'今日首记与娱乐' }}</h2><RouterLink to="/timers">使用额度与计时 →</RouterLink><p v-if="error" class="error">{{ error }}</p><p v-if="notice" role="status">{{ notice }}</p><template v-if="data?.config?.enabled"><p v-if="!compact">{{ data.today }} · 行动奖励已用 {{ data.action_used }}/100</p><p v-if="!compact||!data.daily?.claimed">{{ data.daily?'当天首记已保存':'先保存一条事件或日记即可获得首记资格；无需分析' }}</p><p v-if="data.daily&&!data.daily.claimed&&data.baseline_required" role="status">首记资格已保留；<RouterLink to="/me">选择游戏起点后领取</RouterLink>。</p><button v-if="data.daily&&!data.daily.claimed&&!data.baseline_required" class="btn" :disabled="writes.busy.value" @click="claim">领取首记 3 币</button><p v-if="data.daily">基础娱乐可用 {{ Math.max(0,data.daily.base_seconds-data.daily.used_seconds)/60 }} 分钟，独立于金币。</p></template><p v-if="summaryOnly&&!data?.config?.enabled" class="muted small"><RouterLink to="/rewards/rules">设置基础娱乐与首记领取 →</RouterLink></p><details v-if="!summaryOnly&&(!compact||!data?.config?.enabled)"><summary>{{ data?.config?'试用规则与未来时长设置':'采用已确认的试用规则' }}</summary><p>有效行动 6 / 15 / 25 币；当前主线另加 4 / 10 / 15。单事实最多40，每日行动最多100。签到独立3币；必要休息免费。严格处罚默认关闭，旧账户未来启用，不重算历史。</p><p v-if="data?.config?.pending_timezone" class="muted">新日规则时区 {{ data.config.pending_timezone }} 从 {{ data.config.timezone_effective_at }} 起生效；已有权益与会话保留原时区。</p><p class="muted">节日日历默认中国大陆；显示假期不自动增加礼金资格。</p><RouterLink to="/rewards">娱乐设置与约定 →</RouterLink><label>每日基础娱乐分钟（可为0）<input type="number" min="0" max="1440" v-model.number="minutes"/></label><label><input type="checkbox" v-model="acknowledge"/>我确认未来采用上述规则</label><button class="btn" :disabled="writes.busy.value||!acknowledge" @click="adopt">保存未来规则</button></details></section></template>
